51	function createGitVcsConfig(): VcsConfig {
52	  let filesMapPromise: Promise<GitFileInfoMap> | null = null;
53	
54	  async function getGitFileInfo(filePath: string): Promise<GitFileInfo | null> {
55	    const filesMap = await filesMapPromise;
56	    return filesMap?.get(filePath) ?? null;
57	  }
58	
59	  return {
60	    initialize: ({siteDir}) => {
61	      if (filesMapPromise) {
62	        // We only initialize this VCS once!
63	        // For i18n sites, this permits reading ahead of time for all locales
64	        // so that it only slows down the first locale
65	        // I assume this logic is fine, but we'll see if it causes trouble
66	
67	        // Note: we could also only call "initialize()" once from the outside,
68	        // But maybe it could be useful for custom VCS implementations to be
69	        // able to initialize once per locale?
70	        PerfLogger.log(
71	          'Git Eager VCS strategy already initialized, skipping re-initialization',
72	        );
73	        return;
74	      }
75	
76	      filesMapPromise = PerfLogger.async('Git Eager VCS init', () =>
77	        loadAllGitFilesInfoMap(siteDir),
78	      );
79	      filesMapPromise.catch((error) => {
80	        console.error(
81	          'Failed to initialize the Docusaurus Git Eager VCS strategy',
82	          error,
83	        );
84	      });
85	    },
86	
87	    getFileCreationInfo: async (filePath: string) => {
88	      const fileInfo = await getGitFileInfo(filePath);
89	      return fileInfo?.creation ?? null;
90	    },
91	
92	    getFileLastUpdateInfo: async (filePath: string) => {
93	      const fileInfo = await getGitFileInfo(filePath);
94	      return fileInfo?.lastUpdate ?? null;
95	    },
96	  };
97	}
