120	export async function getFileCommitDate(
121	  file: string,
122	  {
123	    age = 'oldest',
124	    includeAuthor = false,
125	  }: {
126	    age?: 'oldest' | 'newest';
127	    includeAuthor?: boolean;
128	  },
129	): Promise<{
130	  date: Date;
131	  timestamp: number;
132	  author?: string;
133	}> {
134	  if (!hasGit()) {
135	    throw new GitNotFoundError(
136	      `Failed to retrieve git history for "${file}" because git is not installed.`,
137	    );
138	  }
139	
140	  if (!(await fs.pathExists(file))) {
141	    throw new Error(
142	      `Failed to retrieve git history for "${file}" because the file does not exist.`,
143	    );
144	  }
145	
146	  // We add a "RESULT:" prefix to make parsing easier
147	  // See why: https://github.com/facebook/docusaurus/pull/10022
148	  const resultFormat = includeAuthor ? 'RESULT:%ct,%an' : 'RESULT:%ct';
149	
150	  const args = [
151	    `--format=${resultFormat}`,
152	    '--max-count=1',
153	    age === 'oldest' ? '--follow --diff-filter=A' : undefined,
154	  ]
155	    .filter(Boolean)
156	    .join(' ');
157	
158	  // Do not include GPG signature in the log output
159	  // See https://github.com/facebook/docusaurus/pull/10022
160	  const command = `git -c log.showSignature=false log ${args} -- "${path.basename(
161	    file,
162	  )}"`;
163	
164	  const result = (await GitCommandQueue.add(() => {
165	    return execa(command, {
166	      cwd: path.dirname(file),
167	      shell: true,
168	    });
169	  }))!;
170	
171	  if (result.exitCode !== 0) {
172	    throw new Error(
173	      `Failed to retrieve the git history for file "${file}" with exit code ${result.exitCode}: ${result.stderr}`,
174	    );
175	  }
176	
177	  // We only parse the output line starting with our "RESULT:" prefix
178	  // See why https://github.com/facebook/docusaurus/pull/10022
179	  const regex = includeAuthor
180	    ? /(?:^|\n)RESULT:(?<timestamp>\d+),(?<author>.+)(?:$|\n)/
181	    : /(?:^|\n)RESULT:(?<timestamp>\d+)(?:$|\n)/;
182	
183	  const output = result.stdout.trim();
184	
185	  if (!output) {
186	    throw new FileNotTrackedError(
187	      `Failed to retrieve the git history for file "${file}" because the file is not tracked by git.`,
188	    );
189	  }
190	
191	  const match = output.match(regex);
192	
193	  if (!match) {
194	    throw new Error(
195	      `Failed to retrieve the git history for file "${file}" with unexpected output: ${output}`,
196	    );
197	  }
198	
199	  const timestampInSeconds = Number(match.groups!.timestamp);
200	  const timestamp = timestampInSeconds * 1_000;
201	  const date = new Date(timestamp);
202	
203	  if (includeAuthor) {
204	    return {date, timestamp, author: match.groups!.author!};
205	  }
206	  return {date, timestamp};
207	}
